const CFG = $('Vigor config').first().json.vigorConfig;
const headers = $json.headers ?? {};
const b = $json.body ?? $json;

const presented = headers['x-vigor-lab-key'] ?? headers['X-Vigor-Lab-Key'] ?? null;
const expected = CFG.internalToken || null;
